import{_ as a,o as t,c as s,a5 as i}from"./chunks/framework.BwlBv862.js";const m=JSON.parse('{"title":"Réutiliser et examiner les variables d’exécution","description":"","frontmatter":{"title":"Réutiliser et examiner les variables d’exécution","docId":"user.automations.variables","translationKey":"user.automations.variables","locale":"fr","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"20ba9e681b63ffa9aff2ff5d868738d242fd4eab4d520d9e08656760ee8361ba","translationRevision":"acc4f3a79719d384958589a30c249aee1d7c2cda9184b81c49eaf073a552ac83","order":40},"headers":[],"relativePath":"fr/user/automations/variables.md","filePath":"fr/user/automations/variables.md","lastUpdated":1794611623000}'),n={name:"fr/user/automations/variables.md"};function r(o,e,l,u,c,d){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="reuse-and-review-runtime-variables" tabindex="-1">Réutiliser et examiner les variables d’exécution <a class="header-anchor" href="#reuse-and-review-runtime-variables" aria-label="Permalink to &quot;Réutiliser et examiner les variables d’exécution {#reuse-and-review-runtime-variables}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objectif et prérequis {#goal-and-prerequisites}&quot;">​</a></h2><p>Modifier une valeur partagée une seule fois et la réutiliser dans plusieurs actions. Il faut <strong>Automations → Variables</strong> et un hôte prenant en charge les opérations de variables concernées. L’édition typée et les opérations Cloud avec examen apparaissent selon les capacités de l’hôte ; enregistrer localement ne nécessite aucun téléversement.</p><h2 id="save-a-local-value" tabindex="-1">Enregistrer une valeur locale <a class="header-anchor" href="#save-a-local-value" aria-label="Permalink to &quot;Enregistrer une valeur locale {#save-a-local-value}&quot;">​</a></h2><ol><li>Ajoutez une variable nommée <code>showLabel</code>. Les clés commencent par une lettre ou un trait de soulignement et peuvent contenir lettres, chiffres, points, traits de soulignement et traits d’union, jusqu’à <code>64</code> caractères. Évitez les doublons.</li><li>Lorsque l’édition typée est disponible, choisissez le texte et saisissez <code>Émission du soir</code>. Les autres types pris en charge sont nombre, booléen, liste et secret. Les listes utilisent un tableau JSON de chaînes, tel que <code>[&quot;rouge&quot;, &quot;bleu&quot;]</code>.</li><li>Sélectionnez <strong>Save</strong>. Un conflit de révision signifie que la collection enregistrée a changé ; rechargez-la et comparez votre modification prévue à celle-ci.</li><li>Utilisez la valeur enregistrée dans un champ d’action acceptant les modèles :</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{{ globals.showLabel }}: {{ event.user.uniqueId }}</span></span></code></pre></div><ol start="5"><li>Testez une action limitée au journal pour examiner le texte rendu. Modifiez <code>showLabel</code>, enregistrez à nouveau et lancez un nouveau test. Les définitions d’action existantes peuvent réutiliser la valeur actualisée sans réimporter de modèle.</li></ol><p>Les <code>params</code> du modèle sont substitués lors de son application ; les <code>globals</code> sont lues à l’exécution. Une clé d’exécution manquante produit un texte vide : vérifiez donc son orthographe avant de l’utiliser dans une destination ou un identifiant. Utilisez les suggestions de variables du champ pour choisir les chemins d’événement adaptés à son déclencheur.</p><h2 id="review-cloud-changes-separately" tabindex="-1">Examiner séparément les changements Cloud <a class="header-anchor" href="#review-cloud-changes-separately" aria-label="Permalink to &quot;Examiner séparément les changements Cloud {#review-cloud-changes-separately}&quot;">​</a></h2><p>La commande <strong>Changes</strong> de Variables dispose d’opérations natives avec examen d’envoi, récupération, application/adoption et retrait lorsqu’elles sont prises en charge. Enregistrez d’abord les modifications locales, sélectionnez une comparaison, examinez son type et sa valeur, puis choisissez explicitement la direction voulue. Récupérer une proposition Cloud est distinct de son application locale. Retirer une valeur partagée est distinct de la suppression d’une ligne locale.</p><p>Les valeurs secrètes ou bloquées sont masquées dans les comparaisons et ne peuvent pas être envoyées par ce parcours avec examen. Ne transformez jamais un secret en texte ordinaire pour contourner ce blocage.</p><h2 id="expected-result-status-and-recovery" tabindex="-1">Résultat attendu, état et récupération <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to &quot;Résultat attendu, état et récupération {#expected-result-status-and-recovery}&quot;">​</a></h2><p>Les variables locales et le partage avec examen conditionné aux capacités sont disponibles ; enregistrer localement ne téléverse jamais automatiquement. Les clés invalides, valeurs typées invalides et révisions obsolètes bloquent l’enregistrement. Corrigez le champ signalé ou rechargez avant de réessayer. Pour les erreurs de compte, consultez le <a href="./../cloud/account.html">compte Cloud</a> ; pour les comparaisons, consultez <a href="./../cloud/changes.html">Changes</a>.</p>',13)])])}const v=a(n,[["render",r]]);export{m as __pageData,v as default};
